(2007, '04119120075', 8, 'Soft Competency', 'Relationship Building, PL 3', 'Assessment Center', 'Diberikan tanggung jawab untuk mencari pihak-pihak potensial untuk bekerja sama, dan menyusun kegiatan yang relevan untuk memperluas hubungan dan interaksi dengan pihak eksternal', 'Menerjemahkan kebutuhan stakeholder ke dalam inisiatif yang konkret, dengan hasil yang dapat diukur, sehingga memperkuat hubungan kerja dan mencapai tujuan kedua belah pihak.', '2025-01-01', '2026-10-31', NULL, NULL, '2026-02-02 04:21:24', '2026-02-02 04:21:24'),
(2008, '04114120037', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Creating a Harmonious & Goal-Oriented Team', 'Mengenali sumber konflik yang mungkin muncul dan tersedia tindakan mitigasi nyata, sehingga penurunan insiden konflik dan meningkatnya kinerja tim.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2009, '04114120037', 10, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Managing & Innovating Through Change', 'Realisasi KPI melebihi target, melalui penemuan cara kerja baru yang lebih efektif.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2010, '04114120037', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Guiding, Motivating & Inspiring Creativity', 'Inisiasi inovasi dalam tim untuk perbaikan kerja yang mendukung peningkatan produktivitas kerja tim, sehingga mendukung pencapaian target.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2011, '04114120037', 10, 'Soft Competency', 'Decision Making, PL 3', 'Assessment Center', 'Impactful Problem Solving & Decisions', 'Mengintegrasikan informasi dari pihak lain dalam analisis yang komprehensif, ditandai dengan identifikasi isu mendasar dan implementasi solusi yang berdampak luas.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2012, '04114120037', 10, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Strategic Team Development Planning', 'Tersedia rencana pengembangan subordinat sesuai dengan kebutuhan subordinat dan perusahaan, sehingga mendorong peningkatan kompetensi dan potensi subordinat (serta memanfaatkan umpan balik secara efektif).', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2013, '04114120037', 10, 'Soft Competency', 'Relationship Building, PL 3', 'Assessment Center', 'Building Trust & Translating Goals Into Action', 'Terbangunnya kolaborasi dengan pihak potensial yang mendukung pencapaian sasaran perusahaan.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2014, '04114120037', 9, 'Soft Competency', 'Decision Making, PL 3', 'Assessment Center', 'Menganalisis isu masalah jangka pendek-menengah dengan menggunakan pendekatan/teknik/metode analisis tertentu, serta membuat keputusan yang mempertimbangkan dampak efisiensi bagi perusahaan', 'Mengintegrasikan informasi dari pihak lain dalam analisis yang komprehensif, ditandai dengan identifikasi isu mendasar dan implementasi solusi yang berdampak luas.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2015, '04114120037', 9, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Mengidentifikasi kelemahan dan kelebihan anggota tim, menyusun program kerja detail bagi tim, serta menghasilkan rencana pengembangan untuk mendukung kebutuhan tim', 'Tersedia rencana pengembangan subordinat sesuai dengan kebutuhan subordinat dan perusahaan, sehingga mendorong peningkatan kompetensi dan potensi subordinat (serta memanfaatkan umpan balik secara efektif).', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2016, '04114120037', 9, 'Soft Competency', 'Relationship Building, PL 3', 'Assessment Center', 'Identifikasi cara membangun hubungan kerja yang efektif untuk mencapai tujuan bersama, untuk keberhasilan jangka panjang perusahaan', 'Terbangunnya kolaborasi dengan pihak potensial yang mendukung pencapaian sasaran perusahaan.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2017, '04114120037', 8, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Mendokumentasikan dan menganalisis pendekatan yang digunakan dalam penyelesaian konflik serta menyusun strategi untuk diterapkan dalam peran kepemimpinan sendiri', 'Mengenali sumber konflik yang mungkin muncul dan tersedia tindakan mitigasi nyata, sehingga penurunan insiden konflik dan meningkatnya kinerja tim.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2018, '04114120037', 8, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Menganalisis proses kerja/studi kasus untuk mengidentifikasi peluang improvement serta menghasilkan ide-ide perbaikan secara sistematis dan strategis untuk menghasilkan ide inovasi', 'Realisasi KPI melebihi target, melalui penemuan cara kerja baru yang lebih efektif.', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2019, '04114120037', 8, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Mengadakan sesi formal/informal dengan anggota tim untuk mengasah kemampuan mengenali karakteristik tim serta menyusun program pengembangan yang kreatif dan sesuai dengan kebutuhan tim', 'Tersedia rencana pengembangan subordinat sesuai dengan kebutuhan subordinat dan perusahaan, sehingga mendorong peningkatan kompetensi dan potensi subordinat (serta memanfaatkan umpan balik secara efektif).', '2025-01-01', '2025-12-01', NULL, NULL, '2026-02-02 09:07:42', '2026-02-02 09:07:42'),
(2021, '01124080034', 8, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Terlibat dalam suatu lingkungan baru (misalnya suatu project) yang kondisinya dinamis (terdapat perbedaan pendapat/konflik), serta ditugaskan untuk menjaga sinergi dan keharmonisan tim untuk jangka panjang yang melibatkan anggota tim untuk jangka panjang bisnis perusahaan', 'Fulfill Gap', '2026-01-01', '2026-06-01', NULL, NULL, '2026-02-04 10:50:42', '2026-02-04 10:50:42'),
