(2033, '04112030011', 9, 'Soft Competency', 'Synergized Team, PL 4', 'Assessment Center', 'Conduct brainstorming sessions with the supervisor on the most effective methods for knowledge sharing within the team, and discuss ways to facilitate structured knowledge-sharing sessions', 'Actively engage team members in discussions, acknowledge contributions, and provide supportive feedback, leads to stronger trust and improved team performance.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-03-02 03:48:10'),
(2036, '04112030011', 9, 'Soft Competency', 'Adaptive to Change, PL 4', 'Assessment Center', 'Discuss change management strategies within the organization and how to ensure the sustainability of implemented changes', 'Participate in coaching sessions with appointed coach, at least once every three months. [Coach: …]', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-24 09:16:14'),
(2038, '04112030011', 9, 'Soft Competency', 'Manage & Planning, PL 4', 'Assessment Center', 'Develop strategic work plans considering risk mitigation for new task demands outside the initial plan. Hone the ability to create structured tools and monitoring systems to track personal and team progress', 'Cascade business plans into team work plans, optimize resources, and provide mitigation action to overcome obstacles', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-03-02 03:45:50'),
(2041, '04112030011', 9, 'Soft Competency', 'Relationship Building, PL 4', 'Assessment Center', 'Engage in strategic dialogues to gain insights on cultivating and sustaining high-impact relationships with internal and external stakeholders', 'Participate in coaching sessions with appointed coach, at least once every three months. [Coach: …]', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-24 09:15:35'),
(2043, '04112030011', 8, 'Soft Competency', 'Integrity for All Action, PL 4', 'Assessment Center', 'Design and implement an ethical leadership program that ensures all team leaders serve as role models in upholding integrity', 'Serve as a role model and implement systems that reinforce ethical behavior, accountability, and transparency, leads to reduction in the number of SOP violations and the establishment of an integrity-driven organizational culture.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2044, '04112030011', 8, 'Soft Competency', 'Growth for Co Prosperity, PL 4', 'Assessment Center', 'Participate in forums to expand knowledge of future business trends as a basis for formulating company strategies and initiatives that support the organization’s long-term success', 'Develop and implement proactive strategies to anticipate business challenges and changes, ensuring the company is well-prepared for long-term growth and sustainability.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2045, '04112030011', 8, 'Soft Competency', 'Adaptive to Change, PL 4', 'Assessment Center', 'Attend exhibitions, summits, or showcases on the latest innovations to serve as references for implementing innovation ideas within the organization', 'Design and implement systems that foster a culture of innovation, encouraging creativity, experimentation, and continuous improvement within the company.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58');
INSERT INTO `individual_development_plans` (`id`, `employee_id`, `development_model_id`, `competency_type`, `competency_name`, `review_tools`, `development_program`, `expected_outcome`, `time_frame_start`, `time_frame_end`, `realization_date`, `result_evidence`, `created_at`, `updated_at`) VALUES
(2046, '04112030011', 8, 'Soft Competency', 'Passion for Excellence, PL 4', 'Assessment Center', 'Lead challenging strategic projects requiring innovation to achieve targets beyond initial expectations, and conduct performance coaching to help team members surpass standard targets', 'Develop strategies and initiatives that build a performance-driven culture, leads to exceeding KPI\'s beyond target.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2047, '04112030011', 8, 'Soft Competency', 'Manage & Planning, PL 4', 'Assessment Center', 'Be assigned as a Project Lead to execute an innovation idea with a team from various units. This assignment is expected to enhance team conflict management skills in achieving shared goals', 'Cascade business plans into team work plans, optimize resources, and provide mitigation action to overcome obstacles.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2048, '04112030011', 8, 'Soft Competency', 'Decision Making, PL 4', 'Assessment Center', 'Work on case studies regarding strategic issues outside the technical operations of the work area and discuss the analysis results with the supervisor, or act as a project leader involving cross-divisions to hone strategic decision-making', 'Improved decision quality, stronger team alignment, and positive medium to long-term business outcomes.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2049, '04112030011', 8, 'Soft Competency', 'Developing Others, PL 4', 'Assessment Center', 'Assignment to design development programs by identifying strengths and weaknesses, providing feedback, motivating team members, and determining cross-functional development programs to hone competencies and support optimal career advancement for subordinates', 'Design subordinates\' development program based on their characteristics and company needs, leads to enhancing overall team performance.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2050, '04112030011', 8, 'Soft Competency', 'Relationship Building, PL 4', 'Assessment Center', 'Initiate and execute partnership programs with strategic partners that support the company\'s business growth', 'Develop and implement strategies that build long-term collaborative relationships with stakeholders, fostering their commitment to work harmoniously in achieving sustainable long-term organizational goal.', '2026-01-02', '2027-12-31', NULL, NULL, '2026-02-09 06:14:58', '2026-02-09 06:14:58'),
(2053, '01113110009', 10, 'Soft Competency', 'Synergized Team, PL 3', 'Superior Rating', 'Team Facilitation & Communication', 'Berpartisipasi dalam training mengenai Delegative Leadership, sehingga mampu percaya diri dalam menghadapi subordinat dan mendelegasikan tugas-tugas kepada subordinat.', '2026-02-02', '2026-12-31', NULL, NULL, '2026-02-13 06:37:42', '2026-02-25 01:54:46'),
(2054, '04119110035', 10, 'Soft Competency', 'Decision Making, PL 2', 'Project Based Evaluation', 'Data-Driven Decision Making', 'Memahami Root Cause Analysis Method & Analytical Problem Solving', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2055, '04119110035', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 2', 'Project Based Evaluation', 'Harmony Environment', 'Memahami pentingnya team building & collaboration', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2056, '04119110035', 9, 'Technical Competency', 'Growth for Co Prosperity, PL 2', 'Project Based Evaluation', 'Mengobservasi conflict resolution dalam lingkup pekerjaannya untuk sesi coaching dengan Maintenance Section Head', 'Memperoleh strategi conflict resolution dari sesi coaching dengan maintenance section head', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2057, '04119110035', 8, 'Soft Competency', 'Decision Making, PL 2', 'Project Based Evaluation', 'Mengambil peran utama dalam proses pengambilan keputusan dalam proyek yang memiliki tingkat risiko menengah', 'Mampu memimpin inspeksi harian & identifikasi isu tiap bulan dengan metode problem solving kompleks', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2058, '04119110035', 8, 'Soft Competency', 'Decision Making, PL 2', 'Project Based Evaluation', 'Mengerjakan studi kasus baru untuk mengasah kemampuan analisa secara sistematis terutama kasus-kasus baru dan lebih kompleks menggunakan metode analisa seperti SWOT Analysis atau risk assessment', 'Mampu menganalisis masalah operasional & mengambil keputusan dgn data yg valid utk tim', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2059, '04119110035', 8, 'Soft Competency', 'Growth for Co Prosperity, PL 2', 'Project Based Evaluation', 'Mengadakan diskusi berkala dengan tim kerja baik dalam hal formal maupun informal guna menciptakan iklim harmonis serta mengkomunikasikan harapan dan arahan mengenai keselarasan kerja dengan orientasi jangka panjang perusahaan', 'Mampu mengarahkan tim dalam menciptakan iklim kerja harmonis dan melaksanakan pekerjaan berorientasi jangka panjang', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:07:38', '2026-02-13 08:07:38'),
(2060, '04119110035', 9, 'Soft Competency', 'Decision Making, PL 2', 'Project Based Evaluation', 'Mendiskusikan metode pengambilan keputusan yang lebih kompleks, seperti SWOT Analysis atau risk assessment', 'Mampu menganalisis masalah operasional & mengambil keputusan dgn data yg valid utk tim', '2025-12-01', '2026-05-31', NULL, NULL, '2026-02-13 08:09:19', '2026-02-13 08:09:19'),
(2063, '01118030003', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Creating a Harmonious & Goal-Oriented Team', 'Participate in \"Creating a Harmonious & Goal Oriented Team\" Training or other equivalent training covering related subject matter.', '2026-01-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-04-22 02:32:28'),
(2065, '01118030003', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Guiding, Motivating & Inspiring Creativity', 'Participate in \"Guiding, Motivating & Inspiring Creativity\" Training or other equivalent training covering related subject matter.', '2026-01-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-04-22 02:32:59'),
(2066, '01118030003', 10, 'Soft Competency', 'Manage & Planning, PL 3', 'Assessment Center', 'Team Task Planning & Execution', 'Participate in \"Team Task Planning & Execution\" Training or other equivalent training covering related subject matter.', '2026-01-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-04-22 02:33:08'),
(2068, '01118030003', 10, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Strategic Team Development Planning', 'Participate in \"Strategic Team Development Planning\" Training or other equivalent training covering related subject matter.', '2026-01-01', '2026-11-30', '2026-04-16', 'https://drive.google.com/file/d/1N66gyOYOG6aF2Zzp2gujpk-S5hOB0J2X/view?usp=sharing', '2026-02-16 02:18:05', '2026-05-05 01:30:30'),
(2080, '01118030003', 8, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Take responsibility for identifying strategic partners or external parties that can support the company’s long-term business growth', 'Continuous collaboration with external parties evidenced by ≥3 documented cross-division engagements with measurable outcomes (e.g., joint initiatives, resolved issues).', '2026-04-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-06-12 08:12:46'),
(2082, '01118030003', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Assignment to design and implement a short-to-medium term project requiring detailed planning and monitoring (such as resources, identification of organizational needs, and oversight processes)', 'Team KPI achievement ≥100% by end of period; at least one documented feedback session given per subordinate per quarter.', '2026-04-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-06-12 08:13:15'),
(2083, '01118030003', 8, 'Soft Competency', 'Manage & Planning, PL 3', 'Assessment Center', 'Lead a cross-functional project to hone the ability to develop strategic work plans, including re-prioritizing when urgent conditions arise', 'Timely and error-minimized completion of team tasks by setting clear objectives, prioritizing work, and implementing proactive monitoring and control systems that anticipate issues and drive reliable results.', '2026-04-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-04-22 02:36:36'),
(2085, '01118030003', 8, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Attend an HR development method workshop (70:20:10) and try to design subordinate development plans accompanied by monitoring of subordinate capability development', 'Produces a written subordinate development plan (IDP) for each direct report; followed by at least one documented coaching session per subordinate.', '2026-04-01', '2026-11-30', NULL, NULL, '2026-02-16 02:18:05', '2026-06-12 08:14:22'),
(2092, '01118030003', 9, 'Soft Competency', 'Manage & Planning, PL 3', 'Assessment Center', 'Receive support via coaching and mentoring with the supervisor to identify potential obstacles in achieving targets at a higher position/level. Help formulate relevant and achievable solutions', 'Participate in coaching sessions with appointed coach, at least once every three months. [Coach: …]', '2026-04-01', '2026-11-30', NULL, NULL, '2026-02-16 02:21:18', '2026-04-22 02:34:04'),
