(2558, '04123110076', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Memberikan bimbingan atau arahan untuk mendorong peningkatan kinerja anggota tim dalam memenuhi berbagai tuntutan pekerjaan maupun saat menghadapi perubahan', 'Pencapaian KPI tim ≥100% pada akhir periode; minimal satu sesi umpan balik yang terdokumentasi diberikan kepada setiap bawahan per kuartal.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 07:04:43', '2026-07-14 07:04:43'),
(2559, '04123110076', 8, 'Soft Competency', 'Developing Others, PL 2', 'Assessment Center', 'Merancang program pengembangan keterampilan sederhana untuk membantu anggota tim dalam proyek tertentu', 'Menghasilkan minimal 1 Individual Development Program per anggota tim yang terdokumentasi, mencakup hasil penilaian kekuatan dan area pengembangan, prorgram pengembangan, serta evaluasi progres peningkatan kompetensi.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 07:04:43', '2026-07-14 07:04:43'),
(2560, '04120090002', 10, 'Soft Competency', 'Integrity for All Action, PL 3', 'Assessment Center', 'Walking the Talk: The Shadow of the Leader', 'Berpartisipasi dalam training “Walking the Talk” atau setara untuk mengetahui cara menerapkan konsekuensi secara konsisten serta menindaklanjuti pelanggaran sesuai dengan ketentuan yang berlaku.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:58', '2026-07-14 08:26:58'),
(2561, '04120090002', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Conflict Management for Leaders', 'Berpartisipasi dalam training “Conflict Management for Leaders” atau setara untuk mengetahui cara mengarahkan tim agar memiliki orientasi pada peningkatan kinerja yang berkelanjutan serta selaras dengan tujuan jangka panjang organisasi.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:58', '2026-07-14 08:26:58'),
(2562, '04120090002', 10, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Managing & Innovating Through Change', 'Berpartisipasi dalam training “Managing & Innovating Through Change” atau setara untuk mengetahui cara mengembangkan inovasi kerja yang terstruktur sebagai respons terhadap perubahan.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:58', '2026-07-14 08:26:58'),
(2563, '04120090002', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Motivating High Performance', 'Berpartisipasi dalam training “Motivating High Performance” atau setara untuk mendorong tim secara konsisten untuk menghasilkan kinerja di atas standar yang ditetapkan.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:58', '2026-07-14 08:26:58'),
(2564, '04120090002', 8, 'Soft Competency', 'Integrity for All Action, PL 3', 'Assessment Center', 'Penugasan untuk melakukan observasi terhadap potensi dan/atau pelanggaran yang telah terjadi di lingkungan kerja serta memberikan teguran/edukasi pada pihak lain yang tidak menjalankan aturan/norma perusahaan', 'Terdokumentasi 100% hasil observasi dan tindak lanjut, dengan target peningkatan kepatuhan ≥10% serta penurunan pelanggaran berulang ≥10%.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:59', '2026-07-14 08:26:59'),
(2565, '04120090002', 8, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Menganalisis proses kerja/studi kasus untuk mengidentifikasi peluang improvement serta menghasilkan ide-ide perbaikan secara sistematis dan strategis untuk menghasilkan ide inovasi', 'Minimal 1 inovasi kerja terstruktur diimplementasikan dan disesuaikan terhadap perubahan bisnis/proses, didokumentasi dan dimonitor progressnya.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:59', '2026-07-14 08:26:59'),
(2566, '04120090002', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Memberikan bimbingan atau arahan untuk mendorong peningkatan kinerja anggota tim dalam memenuhi berbagai tuntutan pekerjaan maupun saat menghadapi perubahan', 'Pencapaian KPI tim ≥100% pada akhir periode; minimal satu sesi umpan balik yang terdokumentasi diberikan kepada setiap bawahan per kuartal.', '2026-05-01', '2028-04-30', NULL, NULL, '2026-07-14 08:26:59', '2026-07-14 08:26:59'),
(2567, '01114120002', 10, 'Soft Competency', 'Decision Making, PL 3', 'Assessment Center', 'Impactful Problem Solving & Decisions', 'Melakukan problem solving berbasis data menggunakan minimal 2 metode analisis (contoh: 5 Why, Fishbone, Pareto), menghasilkan root cause, corrective action, PIC, timeline, dan monitoring efektivitas penyelesaian.', '2026-08-01', '2026-12-01', NULL, NULL, '2026-07-20 02:10:31', '2026-07-20 03:31:23'),
(2568, '01114120002', 8, 'Technical Competency', 'Policy Making', 'Superior Rating', 'Memimpin proyek standarisasi dan implementasi SOP General Affair Section untuk meningkatkan kepatuhan, meminimalkan risiko fraud, memperkuat tata kelola operasional, serta memastikan pemahaman dan kepatuhan melalui sosialisasi SOP secara berkala.', 'Tersedianya standarisasi SOP General Affair yang efektif sehingga mengurangi pelanggaran SOP, baik oleh pihak internal maupun eksternal, serta meningkatkan kepatuhan operasional.', '2026-08-01', '2026-12-01', NULL, NULL, '2026-07-20 02:48:40', '2026-07-20 02:48:40'),
(2569, '01114120002', 10, 'Technical Competency', 'Fleet Management', 'Self Assessment', 'Fleet Management Training', 'Melakukan monitoring utilisasi kendaraan, biaya operasional, fuel consumption, dan preventive maintenance secara berkala sehingga terdapat laporan fleet performance dan improvement plan.', '2026-08-01', '2026-12-01', NULL, NULL, '2026-07-20 03:34:09', '2026-07-20 03:34:09'),
(2570, '01115020011', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Motivating High Performance', 'Complete the \'Motivating High Performance\' training (or an equivalent program) to learn how to inspire and motivate the team to achieve challenging targets and exceed performance expectations.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 01:29:16', '2026-07-23 01:23:40'),
(2571, '01115020011', 10, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Strategic Team Development Planning', 'Complete the \'Strategic Team Development Planning\' training (or an equivalent program) to learn how to design team development plans using the 70:20:10 development model and effectively monitor subordinate development.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 01:29:16', '2026-07-23 01:23:54'),
(2572, '01115020011', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Provide appropriate coaching and guidance to team members to help them improve their performance in meeting various work demands', 'The team achieves at least 100% of its KPI target by the end of the performance period, and each subordinate receives at least one documented feedback session per quarter.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 01:29:16', '2026-07-23 01:09:13'),
(2573, '01115020011', 8, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Conduct formal/informal sessions with team members to hone the ability for recognize team characteristics and design creative development programs that suit team needs', 'Each subordinate has an Individual Development Plan (IDP) that is documented, implemented, and regularly monitored until the targeted development objectives are achieved.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 01:29:16', '2026-07-23 01:08:22'),
(2574, '01115120002', 10, 'Soft Competency', 'Integrity for All Action, PL 3', 'Assessment Center', 'Walking the Talk: The Shadow of the Leader', 'Complete the \'Walking the Talk\' training (or an equivalent program) to learn how to address violations and follow up in accordance with applicable policies and regulations.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:40:24'),
(2575, '01115120002', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Conflict Management for Leaders', 'Complete the \'Conflict Management for Leaders\' training (or an equivalent program) to learn how to guide the team toward a work orientation that supports the company’s long-term sustainability.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:39:51'),
(2576, '01115120002', 10, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Managing & Innovating Through Change', 'Complete the \'Managing & Innovating Through Change\' training (or an equivalent program) to learn how to develop systematic and strategic innovations in response to change.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:39:23'),
(2577, '01115120002', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Motivating High Performance', 'Complete the \'Motivating High Performance\' training (or an equivalent program) to learn how to motivate the team to deliver performance that exceeds established targets and expectations.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:38:48'),
(2578, '01115120002', 10, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Strategic Team Development Planning', 'Complete the \'Strategic Team Development Planning\' training (or an equivalent program) to learn how to develop more structured development plans and establish monitoring mechanisms for team members’ progress.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:38:20'),
(2579, '01115120002', 10, 'Soft Competency', 'Relationship Building, PL 3', 'Assessment Center', 'Managing Cross-Functional Stakeholder Relationships', 'Complete the \'Managing Cross-Functional Stakeholder Relationships\' training (or an equivalent program) to learn how to build and maintain sustainable trust with external stakeholders and leverage working relationships to create added value in achieving the company’s long-term objectives.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:37:30'),
(2580, '01115120002', 8, 'Soft Competency', 'Integrity for All Action, PL 3', 'Assessment Center', 'Assignment to educate or reprimand parties who do not comply with company rules or norms', 'Conduct at least one integrity reinforcement activity per month and ensure that 100% of integrity violation cases within their authority have documented follow-up actions.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:35:33'),
(2581, '01115120002', 8, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Analyze the latest trends to explore new processes and view matters from various perspectives to generate innovation ideas', 'At least one structured work innovation is implemented and adapted to business/process changes, documented, and its progress is regularly monitored.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:34:48'),
(2582, '01115120002', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Provide appropriate coaching and guidance to team members to help them improve their performance in meeting various work demands', 'The team achieves at least 100% of its KPI target by the end of the performance period, and each subordinate receives at least one documented feedback session per quarter.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:33:32'),
(2583, '01115120002', 8, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Assignment to manage team members to identify strengths and weaknesses, provide feedback, motivate the team, and plan development using the 70:20:10 approach', 'Each subordinate has a documented Individual Development Plan (IDP) that is implemented and regularly monitored until the targeted development goals are achieved.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 06:09:55', '2026-07-23 01:32:51'),
(2584, '04124040154', 10, 'Soft Competency', 'Integrity for All Action, PL 3', 'Assessment Center', 'Walking the Talk: The Shadow of the Leader', 'Mengikuti pelatihan \"Walking the Talk\" atau setara untuk mengetahui cara mengedukasi orang lain agar bertindak selaras dengan prinsip-prinsip etika perusahaan dalam segala situasi dan kondisi.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2585, '04124040154', 10, 'Soft Competency', 'Growth for Co Prosperity, PL 3', 'Assessment Center', 'Conflict Management for Leaders', 'Mengikuti pelatihan \"Conflict Management for Leaders\" atau setara untuk mengetahui cara menjembatani perbedaan di dalam kelompok kerjanya dan juga mengatasi konflik dalam tim.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2586, '04124040154', 10, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Managing & Innovating Through Change', 'Mengikuti pelatihan \"Managing & Innovating Through Change\" atau setara untuk mengetahui cara mempersiapkan orang lain dalam menghadapi perubahan.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2587, '04124040154', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Motivating High Performance', 'Mengikuti pelatihan \"Motivating High Performance\" atau setara untuk mengetahui cara mencari cara baru dan mendorong orang lain untuk mencapai hasil kerja yang melebihi tuntutan pekerjaan saat ini.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2588, '04124040154', 10, 'Soft Competency', 'Decision Making, PL 3', 'Assessment Center', 'Impactful Problem Solving & Decisions', 'Mengikuti pelatihan \"Impactful Problem Solving & Decisions\" atau setara untuk mengetahui cara mengevaluasi keputusan dari berbagai perspektif.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2589, '04124040154', 10, 'Soft Competency', 'Developing Others, PL 3', 'Assessment Center', 'Strategic Team Development Planning', 'Mengikuti pelatihan \"Strategic Team Development Planning\" atau setara untuk mengetahui cara meningkatkan kemampuan dalam merancang rencana pengembangan tim dengan variasi metode pengembangan (70:20:10).', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:24', '2026-07-21 07:13:24'),
(2590, '04124040154', 10, 'Soft Competency', 'Relationship Building, PL 3', 'Assessment Center', 'Managing Cross-Functional Stakeholder Relationships', 'Mengikuti pelatihan \"Managing Cross-Functional Stakeholder Relationships\" atau setara untuk mengetahui cara menjaga hubungan kerja dengan pihak eksternal untuk membangun kepercayaan, mengidentifikasi kebutuhan stakeholder, serta meningkatkan nilai perusahaan dan mendukung tercapainya tujuan bersam', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:25', '2026-07-21 07:13:25'),
(2591, '04124040154', 8, 'Soft Competency', 'Adaptive to Change, PL 3', 'Assessment Center', 'Menganalisis tren terbaru untuk mengeksplorasi proses baru dan melihat suatu hal dari berbagai perspektif untuk menghasilkan ide inovasi', 'Minimal 1 inovasi kerja terstruktur diimplementasikan dan disesuaikan terhadap perubahan bisnis/proses, didokumentasi, sosialisasikan dan dimonitor progressnya.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:25', '2026-07-21 07:13:25'),
(2592, '04124040154', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Melakukan pendampingan dan arahan yang tepat untuk anggota tim guna membantu mereka meningkatkan kinerja dalam menghadapi berbagai tuntutan pekerjaan', 'Tercapainya target jam pelatihan, khususnya di plant, melalui pendampingan dan arahan kepada HRGA Plant.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:25', '2026-07-21 07:13:25'),
(2593, '04124040154', 8, 'Soft Competency', 'Decision Making, PL 3', 'Assessment Center', 'Diberikan tanggung jawab untuk mengambil keputusan atau merumuskan suatu solusi untuk menyelesaikan masalah, dengan tetap memperhatikan efisiensi yang mendukung kepentingan perusahaan', 'Keputusan yang menjadi kewenangan didokumentasikan beserta analisis berbagai alternatif, masukan stakeholder terkait, action plan, PIC, dan target waktu penyelesaian', '2026-08-01', '2026-11-30', NULL, NULL, '2026-07-21 07:13:25', '2026-07-21 07:13:25'),
(2594, '07119040002', 10, 'Technical Competency', 'Persuasive Communication', 'Self Assessment', 'Impactful Negotiation in Business Communication', 'Berpartisipasi dalam training “Impactful Negotiation in Business Communication” atau training lain yang setara dengan materi terkait.', '2026-08-01', '2026-12-30', NULL, NULL, '2026-07-23 04:18:15', '2026-08-03 09:06:21'),
(2595, '07119040002', 8, 'Technical Competency', 'Persuasive Communication', 'Self Assessment', 'Melakukan negosiasi strategis dengan pihak setempat untuk memperoleh kesepakatan optimal terkait lokasi operasional, sehingga mendukung efisiensi akses, mobilisasi, dan biaya kegiatan harvesting tanpa mengurangi efektivitas operasional tanaman industri.', 'Dokumentasi kesepakatan strategis dengan stakeholder lokal beserta dampak improvement operasional dan cost saving melalui Operational Improvement Report dan Cost Saving/Cost Improvement Report.', '2026-08-01', '2026-12-30', NULL, NULL, '2026-07-23 04:31:19', '2026-08-03 09:07:00'),
(2596, '04123110088', 10, 'Technical Competency', 'Work Automation', 'Self Assessment', 'Digital Data Management & Workflow Automation untuk Supervisor Proyek', 'Berpartisipasi dalam training terkait otomatiasai workflow untuk Supervisor Proyek, seperti digital data collection & data management.', '2026-08-01', '2026-12-30', NULL, NULL, '2026-07-23 04:39:55', '2026-08-03 09:08:45'),
(2597, '07120010003', 10, 'Technical Competency', 'Excel', 'Self Assessment', 'Intermediate to Advanced Level of Excel', 'Berpartisipasi dalam workshop excel, sehingga mampu mendukung pelaporan balance budget.', '2026-08-01', '2026-12-30', NULL, NULL, '2026-07-23 04:47:24', '2026-08-03 09:05:13'),
(2598, '07120010003', 9, 'Technical Competency', 'Project Administration', 'Self Assessment', 'Mengikuti mentoring terkait penyusunan laporan berbasis data dan perhitungan balance budget untuk meningkatkan kemampuan analisis, akurasi pelaporan, dan pengelolaan anggaran operasional. [Mentor: Ahmad Mudhofir]', 'Tersedianya laporan perhitungan balance budget yang tepat waktu, akurat, dan sesuai standar perusahaan melalui penerapan kemampuan advanced Excel, guna mendukung monitoring serta evaluasi anggaran operasional.', '2026-08-01', '2026-12-30', NULL, NULL, '2026-07-23 04:56:13', '2026-08-03 09:05:21'),
(2599, '04123110077', 10, 'Technical Competency', 'Communication', 'Self Assessment', 'Leadership Communication: Impactful and Persuasive', 'Berpartisipasi dalam training komunikasi kepemimpinan untuk membangun gaya komunikasi yang persuasif dan berdampak guna mendukung efektivitas komunikasi dalam peran saat ini', '2026-08-01', '2026-12-30', NULL, NULL, '2026-08-03 08:58:22', '2026-08-03 09:07:46'),
(2600, '01113040005', 10, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Guiding, Motivating & Inspiring Creativity', 'Berpartisipasi dalam training “Guiding, Motivating & Inspiring Creativity” atau training lain yang setara dengan materi terkait.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-08-05 05:50:26', '2026-08-05 05:50:26'),
(2601, '01113040005', 10, 'Technical Competency', 'Excel', 'Self Assessment', 'Intermediate Level of Excel', 'Berpartisipasi dalam workshop excel, sehingga mampu mendukung pelaporan balance budget.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-08-05 05:51:19', '2026-08-05 05:51:19'),
(2602, '01113040005', 8, 'Soft Competency', 'Passion for Excellence, PL 3', 'Assessment Center', 'Melakukan pendampingan dan arahan yang tepat untuk anggota tim guna membantu mereka meningkatkan kinerja dalam menghadapi berbagai tuntutan pekerjaan', 'Terdokumentasinya sesi feedback rutin kepada setiap bawahan secara kuartalan serta tercapainya target proyek yang melampaui ekspektasi, seperti penyelesaian pekerjaan lebih cepat dari timeline yang telah ditetapkan.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-08-05 05:52:04', '2026-08-05 05:52:04'),
(2603, '01113040005', 9, 'Technical Competency', 'Project Administration', 'Self Assessment', 'Mengikuti mentoring terkait penyusunan laporan berbasis data dan perhitungan balance budget untuk meningkatkan kemampuan analisis, akurasi pelaporan, dan pengelolaan anggaran operasional. [Mentor: Ahmad Mudhofir]', 'Tersedianya laporan perhitungan balance budget yang tepat waktu, akurat, dan sesuai standar perusahaan melalui penerapan kemampuan advanced Excel, guna mendukung monitoring serta evaluasi anggaran operasional.', '2026-08-01', '2026-11-30', NULL, NULL, '2026-08-05 05:52:52', '2026-08-05 05:52:52');
